	read.EXOModuleEnabled = reconcile.KeepBool(cfg.EXOModuleEnabled, read.EXOModuleEnabled)
	read.Fax = reconcile.KeepStr(cfg.Fax, read.Fax)
	read.FirstName = reconcile.KeepStr(cfg.FirstName, read.FirstName)
	read.GeoCoordinates = reconcile.KeepStr(cfg.GeoCoordinates, read.GeoCoordinates)
